using UniversityCatalog.Models;

namespace UniversityCatalog.Services;

public class InMemoryCatalogService : ICatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public InMemoryCatalogService()
    {
        _departments =
        [
            new() { Code = "CS",   Name = "Computer Science" },
            new() { Code = "MATH", Name = "Mathematics" },
            new() { Code = "PHYS", Name = "Physics" },
            new() { Code = "ENG",  Name = "English" },
            new() { Code = "HIST", Name = "History" },
        ];

        _courses =
        [
            new()
            {
                Id = 1, Code = "CS 101", Title = "Introduction to Computer Science",
                Description = "A broad introduction to the field of computer science covering computational thinking, basic programming in Python, data representation, and an overview of modern computing topics including AI, networking, and cybersecurity.",
                Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", DepartmentCode = "CS", IsFeatured = true,
                Instructor = new() { Name = "Dr. Ada Lovelace", Title = "Professor", Email = "lovelace@university.edu",
                    Bio = "Dr. Lovelace has over 15 years of experience teaching introductory CS courses. Her research focuses on computing education and curriculum design." }
            },
            new()
            {
                Id = 2, Code = "CS 201", Title = "Data Structures and Algorithms",
                Description = "Study of fundamental data structures (arrays, linked lists, trees, hash tables, graphs) and algorithm design techniques (divide-and-conquer, dynamic programming, greedy algorithms). Includes complexity analysis using Big-O notation.",
                Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM", DepartmentCode = "CS", IsFeatured = true,
                Instructor = new() { Name = "Dr. Alan Turing", Title = "Associate Professor", Email = "turing@university.edu",
                    Bio = "Dr. Turing specializes in algorithm optimization and theoretical computer science. He has published extensively on graph algorithms and computational complexity." }
            },
            new()
            {
                Id = 3, Code = "CS 310", Title = "Database Systems",
                Description = "Principles of database design, relational algebra, SQL, normalization, transaction processing, and an introduction to NoSQL databases. Students complete a semester-long project building a full database application.",
                Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", DepartmentCode = "CS", IsFeatured = false,
                Instructor = new() { Name = "Dr. Edgar Codd", Title = "Professor", Email = "codd@university.edu",
                    Bio = "Dr. Codd is a leading researcher in relational database theory and has contributed to several open-source database projects." }
            },
            new()
            {
                Id = 4, Code = "MATH 101", Title = "Calculus I",
                Description = "Limits, continuity, derivatives of single-variable functions, and an introduction to integration. Applications to physics, engineering, and economics are explored throughout the course.",
                Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", DepartmentCode = "MATH", IsFeatured = true,
                Instructor = new() { Name = "Dr. Isaac Newton", Title = "Distinguished Professor", Email = "newton@university.edu",
                    Bio = "Dr. Newton is an award-winning mathematics educator known for making calculus accessible and engaging for first-year students." }
            },
            new()
            {
                Id = 5, Code = "MATH 220", Title = "Linear Algebra",
                Description = "Vector spaces, matrices, determinants, eigenvalues and eigenvectors, linear transformations, and inner product spaces. Applications to computer graphics, data science, and engineering.",
                Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", DepartmentCode = "MATH", IsFeatured = false,
                Instructor = new() { Name = "Dr. Emmy Noether", Title = "Professor", Email = "noether@university.edu",
                    Bio = "Dr. Noether's research bridges abstract algebra and applied mathematics. She has won multiple teaching excellence awards." }
            },
            new()
            {
                Id = 6, Code = "PHYS 101", Title = "General Physics I",
                Description = "Mechanics, thermodynamics, and waves. Includes weekly lab sessions where students design and conduct experiments to reinforce lecture concepts.",
                Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM + Thu Lab 2:00–4:50 PM", DepartmentCode = "PHYS", IsFeatured = true,
                Instructor = new() { Name = "Dr. Marie Curie", Title = "Professor", Email = "curie@university.edu",
                    Bio = "Dr. Curie is a renowned physicist whose research in materials science has been featured in leading journals. She is passionate about hands-on laboratory education." }
            },
            new()
            {
                Id = 7, Code = "PHYS 250", Title = "Modern Physics",
                Description = "Special relativity, quantum mechanics, atomic and nuclear physics, and elementary particles. Builds on the foundation of General Physics I and Calculus II.",
                Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", DepartmentCode = "PHYS", IsFeatured = false,
                Instructor = new() { Name = "Dr. Richard Feynman", Title = "Associate Professor", Email = "feynman@university.edu",
                    Bio = "Dr. Feynman is celebrated for his clear and entertaining lecture style. His research focuses on quantum computing and its physical foundations." }
            },
            new()
            {
                Id = 8, Code = "ENG 110", Title = "Academic Writing",
                Description = "Develop critical reading, analytical thinking, and clear writing skills. Students write multiple essays exploring argumentation, research-based writing, and rhetorical analysis.",
                Credits = 3, Schedule = "Mon/Wed 9:00–10:20 AM", DepartmentCode = "ENG", IsFeatured = false,
                Instructor = new() { Name = "Prof. Virginia Woolf", Title = "Senior Lecturer", Email = "woolf@university.edu",
                    Bio = "Prof. Woolf has taught writing at the university level for over 20 years and has published two textbooks on academic composition." }
            },
            new()
            {
                Id = 9, Code = "ENG 250", Title = "World Literature",
                Description = "A survey of major literary works from around the globe, spanning ancient epics to contemporary novels. Emphasizes close reading, cultural context, and comparative analysis.",
                Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:20 PM", DepartmentCode = "ENG", IsFeatured = false,
                Instructor = new() { Name = "Dr. Chinua Achebe", Title = "Professor", Email = "achebe@university.edu",
                    Bio = "Dr. Achebe is an expert in postcolonial literature and has lectured internationally on African literary traditions." }
            },
            new()
            {
                Id = 10, Code = "HIST 101", Title = "World History to 1500",
                Description = "Survey of major civilizations, cultural exchanges, and turning points in world history from prehistory through the late medieval period. Covers Mesopotamia, Egypt, Greece, Rome, China, the Islamic world, and the Americas.",
                Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", DepartmentCode = "HIST", IsFeatured = false,
                Instructor = new() { Name = "Dr. Herodotus Smith", Title = "Associate Professor", Email = "smith@university.edu",
                    Bio = "Dr. Smith specializes in ancient Mediterranean civilizations and has led archaeological fieldwork in Greece and Turkey." }
            },
            new()
            {
                Id = 11, Code = "HIST 210", Title = "The American Revolution",
                Description = "In-depth study of the causes, key events, and consequences of the American Revolution. Examines political philosophy, military campaigns, and the experience of diverse groups including women, enslaved people, and Indigenous nations.",
                Credits = 3, Schedule = "Tue/Thu 2:30–3:50 PM", DepartmentCode = "HIST", IsFeatured = false,
                Instructor = new() { Name = "Dr. Abigail Adams", Title = "Professor", Email = "adams@university.edu",
                    Bio = "Dr. Adams is a historian of early America whose books on revolutionary-era politics have received national awards." }
            },
            new()
            {
                Id = 12, Code = "CS 450", Title = "Machine Learning",
                Description = "Supervised and unsupervised learning, neural networks, support vector machines, decision trees, and ensemble methods. Students implement algorithms from scratch and apply them to real-world datasets.",
                Credits = 3, Schedule = "Tue/Thu 3:30–4:50 PM", DepartmentCode = "CS", IsFeatured = true,
                Instructor = new() { Name = "Dr. Ada Lovelace", Title = "Professor", Email = "lovelace@university.edu",
                    Bio = "Dr. Lovelace has over 15 years of experience teaching introductory CS courses. Her research focuses on computing education and curriculum design." }
            },
        ];
    }

    public IReadOnlyList<Department> GetDepartments() => _departments.AsReadOnly();

    public IReadOnlyList<Course> GetCourses(string? search = null, string? departmentCode = null)
    {
        IEnumerable<Course> query = _courses;

        if (!string.IsNullOrWhiteSpace(departmentCode))
        {
            query = query.Where(c => c.DepartmentCode.Equals(departmentCode, StringComparison.OrdinalIgnoreCase));
        }

        if (!string.IsNullOrWhiteSpace(search))
        {
            var term = search.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.OrderBy(c => c.Code).ToList().AsReadOnly();
    }

    public IReadOnlyList<Course> GetFeaturedCourses() =>
        _courses.Where(c => c.IsFeatured).ToList().AsReadOnly();

    public Course? GetCourseById(int id) =>
        _courses.FirstOrDefault(c => c.Id == id);
}

