@using UniversityCatalog.Models

<div class="card h-100 shadow-sm">
    <div class="card-body d-flex flex-column">
        <span class="badge bg-secondary mb-2 align-self-start">@Course.Code</span>
        <h5 class="card-title">@Course.Title</h5>
        <p class="card-text text-muted flex-grow-1">@Truncate(Course.Description, 120)</p>
        <div class="d-flex justify-content-between align-items-center mt-2">
            <small class="text-body-secondary">@Course.Credits credits</small>
            <a href="courses/@Course.Id" class="btn btn-sm btn-outline-primary">View Details</a>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public Course Course { get; set; } = default!;

    private static string Truncate(string text, int maxLength) =>
        text.Length <= maxLength ? text : string.Concat(text.AsSpan(0, maxLength), "…");
}

@using UniversityCatalog.Models

<div class="list-group">
    @foreach (var dept in Departments)
    {
        <a href="courses?department=@dept.Code" class="list-group-item list-group-item-action d-flex justify-content-between align-items-center">
            @dept.Name
            <span class="badge bg-primary rounded-pill">@dept.Code</span>
        </a>
    }
</div>

@code {
    [Parameter, EditorRequired]
    public IReadOnlyList<Department> Departments { get; set; } = [];
}

@using UniversityCatalog.Models

<div class="row row-cols-1 row-cols-md-2 row-cols-lg-3 g-4">
    @foreach (var course in Courses)
    {
        <div class="col">
            <CourseCard Course="course" />
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired]
    public IReadOnlyList<Course> Courses { get; set; } = [];
}

@using UniversityCatalog.Models

<div class="row mb-4">
    <div class="col-md-8">
        <form method="get" class="input-group">
            @if (!string.IsNullOrEmpty(Department))
            {
                <input type="hidden" name="department" value="@Department" />
            }
            <input type="text" name="search" value="@Search" class="form-control" placeholder="Search courses by title, code, or keyword…" />
            <button type="submit" class="btn btn-primary">Search</button>
            @if (!string.IsNullOrEmpty(Search) || !string.IsNullOrEmpty(Department))
            {
                <a href="courses" class="btn btn-outline-secondary">Clear</a>
            }
        </form>
    </div>
    <div class="col-md-4">
        <form method="get">
            @if (!string.IsNullOrEmpty(Search))
            {
                <input type="hidden" name="search" value="@Search" />
            }
            <select name="department" class="form-select" onchange="this.form.submit()">
                <option value="">All Departments</option>
                @foreach (var dept in Departments)
                {
                    <option value="@dept.Code" selected="@(dept.Code == Department)">@dept.Name</option>
                }
            </select>
        </form>
    </div>
</div>

@code {
    [Parameter] public string? Search { get; set; }
    [Parameter] public string? Department { get; set; }

    [Parameter, EditorRequired]
    public IReadOnlyList<Models.Department> Departments { get; set; } = [];
}

