﻿@page "/"
@using UniversityCatalog.Services
@using UniversityCatalog.Components.Shared
@inject ICatalogService Catalog

<PageTitle>University Course Catalog</PageTitle>

<div class="text-center py-4 mb-4 bg-light rounded-3">
    <h1 class="display-5 fw-bold">University Course Catalog</h1>
    <p class="lead text-muted">Browse courses, explore departments, and enroll for the upcoming semester.</p>
    <a href="courses" class="btn btn-primary btn-lg me-2">Browse All Courses</a>
    <a href="enroll" class="btn btn-outline-primary btn-lg">Enroll Now</a>
</div>

<section class="mb-5">
    <h2 class="mb-3">Featured Courses</h2>
    <CourseList Courses="featuredCourses" />
</section>

<section>
    <h2 class="mb-3">Departments</h2>
    <DepartmentLinks Departments="departments" />
</section>

@code {
    private IReadOnlyList<Models.Course> featuredCourses = [];
    private IReadOnlyList<Models.Department> departments = [];

    protected override void OnInitialized()
    {
        featuredCourses = Catalog.GetFeaturedCourses();
        departments = Catalog.GetDepartments();
    }
}

toolArgs.file_text:
@page "/courses/{Id:int}"
@using UniversityCatalog.Services
@using UniversityCatalog.Components.Shared
@inject ICatalogService Catalog

@if (course is null)
{
    <PageTitle>Course Not Found</PageTitle>
    <div class="alert alert-warning">
        <h4>Course not found</h4>
        <p>The course you're looking for doesn't exist. <a href="courses">Back to catalog</a></p>
    </div>
}
else
{
    <PageTitle>@course.Code — University Catalog</PageTitle>

    <nav aria-label="breadcrumb" class="mb-3">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="courses">Courses</a></li>
            <li class="breadcrumb-item"><a href="courses?department=@course.DepartmentCode">@course.DepartmentCode</a></li>
            <li class="breadcrumb-item active" aria-current="page">@course.Code</li>
        </ol>
    </nav>

    <h1>@course.Title</h1>
    <span class="badge bg-secondary fs-6 me-2">@course.Code</span>
    <span class="badge bg-info fs-6">@course.Credits Credits</span>

    <div class="row mt-4">
        <div class="col-lg-8">
            <h4>Description</h4>
            <p>@course.Description</p>

            <h4>Schedule</h4>
            <p><span class="bi bi-clock"></span> @course.Schedule</p>

            <a href="enroll?courseId=@course.Id" class="btn btn-primary mt-2">Enroll in This Course</a>
        </div>
        <div class="col-lg-4">
            <h4>Instructor</h4>
            <InstructorBio Instructor="course.Instructor" />
        </div>
    </div>
}

@code {
    [Parameter] public int Id { get; set; }

    private Models.Course? course;

    protected override void OnInitialized()
    {
        course = Catalog.GetCourseById(Id);
    }
}

@page "/enroll"
@using UniversityCatalog.Models
@using UniversityCatalog.Services
@inject ICatalogService Catalog

<PageTitle>Enroll — University Catalog</PageTitle>

<h1 class="mb-3">Enrollment Request</h1>

@if (submitted)
{
    <div class="alert alert-success">
        <h4 class="alert-heading">Request Submitted!</h4>
        <p>Thank you, <strong>@Model.FullName</strong>. Your enrollment request for
            <strong>@(courses.FirstOrDefault(c => c.Id == Model.CourseId)?.Title ?? "the selected course")</strong>
            has been received. You will receive a confirmation email at your university account.</p>
        <hr />
        <a href="enroll" class="btn btn-outline-success">Submit Another Request</a>
        <a href="courses" class="btn btn-outline-primary ms-2">Back to Catalog</a>
    </div>
}
else
{
    <p class="text-muted">Fill out the form below to request enrollment in a course. All fields are required.</p>

    <div class="row">
        <div class="col-lg-7">
            <EditForm Model="Model" FormName="enrollment" method="post" OnValidSubmit="HandleSubmit">
                <AntiforgeryToken />
                <DataAnnotationsValidator />

                <div class="mb-3">
                    <label for="fullName" class="form-label">Full Name</label>
                    <InputText id="fullName" @bind-Value="Model.FullName" class="form-control" />
                    <ValidationMessage For="() => Model.FullName" />
                </div>

                <div class="mb-3">
                    <label for="studentId" class="form-label">Student ID</label>
                    <InputText id="studentId" @bind-Value="Model.StudentId" class="form-control" placeholder="e.g. ABC123" />
                    <ValidationMessage For="() => Model.StudentId" />
                </div>

                <div class="mb-3">
                    <label for="courseId" class="form-label">Course</label>
                    <InputSelect id="courseId" @bind-Value="Model.CourseId" class="form-select">
                        <option value="0">— Select a course —</option>
                        @foreach (var course in courses)
                        {
                            <option value="@course.Id">@course.Code — @course.Title (@course.Credits cr)</option>
                        }
                    </InputSelect>
                    <ValidationMessage For="() => Model.CourseId" />
                </div>

                <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
                <a href="courses" class="btn btn-outline-secondary ms-2">Cancel</a>
            </EditForm>
        </div>
    </div>
}

@code {
    [SupplyParameterFromForm]
    private EnrollmentRequest Model { get; set; } = new();

    [SupplyParameterFromQuery]
    public int? CourseId { get; set; }

    private IReadOnlyList<Course> courses = [];
    private bool submitted;

    protected override void OnInitialized()
    {
        courses = Catalog.GetCourses();

        if (CourseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = CourseId.Value;
        }
    }

    private void HandleSubmit()
    {
        submitted = true;
    }
}

